using System;
using System.Security.Cryptography.X509Certificates;

namespace RainPointClient.Tests;

// Public test certificates only; the generation keys are discarded. No machine trust changes.
// Fixed 2020-2120 validity (expired leaf ends in 2021) keeps the same TLS assertions portable.
internal static class TestCertificates
	{
	internal static X509Certificate2 ClientOnly () => Load (ClientOnlyDer);
	internal static X509Certificate2 Root () => Load (RootDer);
	internal static X509Certificate2 Leaf (bool expired) => Load (expired ? ExpiredDer : ValidDer);
	private static X509Certificate2 Load (string value)
		{
#if NET10_0_OR_GREATER
  return X509CertificateLoader.LoadCertificate (Convert.FromBase64String (value));
#else
		return new X509Certificate2 (Convert.FromBase64String (value));
#endif
		}
	private const string RootDer = "";
	private const string ValidDer = "";
	private const string ExpiredDer = "";
	private const string ClientOnlyDer = "";
	}